/**
 * A harness id mapped to a provider name the GenAI registry defines.
 * Anything else is the custom value `other`. The registry has no member
 * named `other`.
 */
export const PROVIDER = {
	claudeCode: "anthropic",
	codex: "openai",
	grokBuild: "x_ai",
	gemini: "gcp.gemini",
	other: "other",
} as const;

/** Closed classes for `error.type`. Anything else is `_OTHER`. */
export const ERROR_TYPE = {
	finished: "finished",
	guardBudget: "guard.budget",
	guardTurns: "guard.turns",
	guardLooping: "guard.looping",
	guardIdle: "guard.idle",
	guardMaxSteps: "guard.max_steps",
	stopTime: "stop_time",
	agentUsageLimit: "agent.usage_limit",
	agentNetwork: "agent.network",
	agentSignedOut: "agent.signed_out",
	stoppedByPerson: "stopped_by_person",
	other: "_OTHER",
} as const;

/** Span name prefixes the export writes. */
export const SPAN = {
	step: "nightshift.step",
	gate: "gate",
	wait: "wait",
} as const;

/** `gen_ai.token.modality` when the modality cannot be determined. */
export const TOKEN_MODALITY = {
	audio: "audio",
	image: "image",
	text: "text",
	unknown: "unknown",
} as const;

/** The name of the service every span and point comes from. */
export const SERVICE_NAME = "nightshift";

/** Usage event names. Phase 1 emits them. Phase 0 only validates one. */
